//! Port of `internal/types/errors/code_string.go`.
//!
//! The Go file uses a packed string + index-array trick (generated by
//! `stringer`); we just write a match arm per variant, which is roughly the
//! same size after compilation and far easier to maintain by hand.

use std::fmt;

use crate::codes::Code;

impl Code {
    /// Returns the variant's identifier as a string slice, matching Go's
    /// `(Code).String()`.
    pub fn name(self) -> &'static str {
        use Code::*;
        match self {
            InvalidSyntaxTree => "InvalidSyntaxTree",
            Test => "Test",
            BlankPkgName => "BlankPkgName",
            MismatchedPkgName => "MismatchedPkgName",
            InvalidPkgUse => "InvalidPkgUse",
            BadImportPath => "BadImportPath",
            BrokenImport => "BrokenImport",
            ImportCRenamed => "ImportCRenamed",
            UnusedImport => "UnusedImport",
            InvalidInitCycle => "InvalidInitCycle",
            DuplicateDecl => "DuplicateDecl",
            InvalidDeclCycle => "InvalidDeclCycle",
            InvalidTypeCycle => "InvalidTypeCycle",
            InvalidConstInit => "InvalidConstInit",
            InvalidConstVal => "InvalidConstVal",
            InvalidConstType => "InvalidConstType",
            UntypedNilUse => "UntypedNilUse",
            WrongAssignCount => "WrongAssignCount",
            UnassignableOperand => "UnassignableOperand",
            NoNewVar => "NoNewVar",
            MultiValAssignOp => "MultiValAssignOp",
            InvalidIfaceAssign => "InvalidIfaceAssign",
            InvalidChanAssign => "InvalidChanAssign",
            IncompatibleAssign => "IncompatibleAssign",
            UnaddressableFieldAssign => "UnaddressableFieldAssign",
            NotAType => "NotAType",
            InvalidArrayLen => "InvalidArrayLen",
            BlankIfaceMethod => "BlankIfaceMethod",
            IncomparableMapKey => "IncomparableMapKey",
            InvalidPtrEmbed => "InvalidPtrEmbed",
            BadRecv => "BadRecv",
            InvalidRecv => "InvalidRecv",
            DuplicateFieldAndMethod => "DuplicateFieldAndMethod",
            DuplicateMethod => "DuplicateMethod",
            InvalidBlank => "InvalidBlank",
            InvalidIota => "InvalidIota",
            MissingInitBody => "MissingInitBody",
            InvalidInitSig => "InvalidInitSig",
            InvalidInitDecl => "InvalidInitDecl",
            InvalidMainDecl => "InvalidMainDecl",
            TooManyValues => "TooManyValues",
            NotAnExpr => "NotAnExpr",
            TruncatedFloat => "TruncatedFloat",
            NumericOverflow => "NumericOverflow",
            UndefinedOp => "UndefinedOp",
            MismatchedTypes => "MismatchedTypes",
            DivByZero => "DivByZero",
            NonNumericIncDec => "NonNumericIncDec",
            UnaddressableOperand => "UnaddressableOperand",
            InvalidIndirection => "InvalidIndirection",
            NonIndexableOperand => "NonIndexableOperand",
            InvalidIndex => "InvalidIndex",
            SwappedSliceIndices => "SwappedSliceIndices",
            NonSliceableOperand => "NonSliceableOperand",
            InvalidSliceExpr => "InvalidSliceExpr",
            InvalidShiftCount => "InvalidShiftCount",
            InvalidShiftOperand => "InvalidShiftOperand",
            InvalidReceive => "InvalidReceive",
            InvalidSend => "InvalidSend",
            DuplicateLitKey => "DuplicateLitKey",
            MissingLitKey => "MissingLitKey",
            InvalidLitIndex => "InvalidLitIndex",
            OversizeArrayLit => "OversizeArrayLit",
            MixedStructLit => "MixedStructLit",
            InvalidStructLit => "InvalidStructLit",
            MissingLitField => "MissingLitField",
            DuplicateLitField => "DuplicateLitField",
            UnexportedLitField => "UnexportedLitField",
            InvalidLitField => "InvalidLitField",
            UntypedLit => "UntypedLit",
            InvalidLit => "InvalidLit",
            AmbiguousSelector => "AmbiguousSelector",
            UndeclaredImportedName => "UndeclaredImportedName",
            UnexportedName => "UnexportedName",
            UndeclaredName => "UndeclaredName",
            MissingFieldOrMethod => "MissingFieldOrMethod",
            BadDotDotDotSyntax => "BadDotDotDotSyntax",
            NonVariadicDotDotDot => "NonVariadicDotDotDot",
            InvalidDotDotDot => "InvalidDotDotDot",
            UncalledBuiltin => "UncalledBuiltin",
            InvalidAppend => "InvalidAppend",
            InvalidCap => "InvalidCap",
            InvalidClose => "InvalidClose",
            InvalidCopy => "InvalidCopy",
            InvalidComplex => "InvalidComplex",
            InvalidDelete => "InvalidDelete",
            InvalidImag => "InvalidImag",
            InvalidLen => "InvalidLen",
            SwappedMakeArgs => "SwappedMakeArgs",
            InvalidMake => "InvalidMake",
            InvalidReal => "InvalidReal",
            InvalidAssert => "InvalidAssert",
            ImpossibleAssert => "ImpossibleAssert",
            InvalidConversion => "InvalidConversion",
            InvalidUntypedConversion => "InvalidUntypedConversion",
            BadOffsetofSyntax => "BadOffsetofSyntax",
            InvalidOffsetof => "InvalidOffsetof",
            UnusedExpr => "UnusedExpr",
            UnusedVar => "UnusedVar",
            MissingReturn => "MissingReturn",
            WrongResultCount => "WrongResultCount",
            OutOfScopeResult => "OutOfScopeResult",
            InvalidCond => "InvalidCond",
            InvalidPostDecl => "InvalidPostDecl",
            InvalidIterVar => "InvalidIterVar",
            InvalidRangeExpr => "InvalidRangeExpr",
            MisplacedBreak => "MisplacedBreak",
            MisplacedContinue => "MisplacedContinue",
            MisplacedFallthrough => "MisplacedFallthrough",
            DuplicateCase => "DuplicateCase",
            DuplicateDefault => "DuplicateDefault",
            BadTypeKeyword => "BadTypeKeyword",
            InvalidTypeSwitch => "InvalidTypeSwitch",
            InvalidExprSwitch => "InvalidExprSwitch",
            InvalidSelectCase => "InvalidSelectCase",
            UndeclaredLabel => "UndeclaredLabel",
            DuplicateLabel => "DuplicateLabel",
            MisplacedLabel => "MisplacedLabel",
            UnusedLabel => "UnusedLabel",
            JumpOverDecl => "JumpOverDecl",
            JumpIntoBlock => "JumpIntoBlock",
            InvalidMethodExpr => "InvalidMethodExpr",
            WrongArgCount => "WrongArgCount",
            InvalidCall => "InvalidCall",
            UnusedResults => "UnusedResults",
            InvalidDefer => "InvalidDefer",
            InvalidGo => "InvalidGo",
            BadDecl => "BadDecl",
            RepeatedDecl => "RepeatedDecl",
            InvalidUnsafeAdd => "InvalidUnsafeAdd",
            InvalidUnsafeSlice => "InvalidUnsafeSlice",
            UnsupportedFeature => "UnsupportedFeature",
            NotAGenericType => "NotAGenericType",
            WrongTypeArgCount => "WrongTypeArgCount",
            CannotInferTypeArgs => "CannotInferTypeArgs",
            InvalidTypeArg => "InvalidTypeArg",
            InvalidInstanceCycle => "InvalidInstanceCycle",
            InvalidUnion => "InvalidUnion",
            MisplacedConstraintIface => "MisplacedConstraintIface",
            InvalidMethodTypeParams => "InvalidMethodTypeParams",
            MisplacedTypeParam => "MisplacedTypeParam",
            InvalidUnsafeSliceData => "InvalidUnsafeSliceData",
            InvalidUnsafeString => "InvalidUnsafeString",
            InvalidClear => "InvalidClear",
            TypeTooLarge => "TypeTooLarge",
            InvalidMinMaxOperand => "InvalidMinMaxOperand",
            TooNew => "TooNew",
        }
    }
}

impl fmt::Display for Code {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name())
    }
}
